def save(p,d):p.write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n')
q=load(root/'data/fulltext-review-queue.json');d=load(root/'curation/fulltext-review-decisions.json');decisions={(r['record_id'],r['pmid']):r for r in d['decisions']};counts=collections.Counter();access=collections.Counter()
for a in q['articles']:
 reviewed=[];pending=[]
 for claim in a['claims']:
  rid=claim['record_id'];decision=decisions.get((rid,a['pmid']))
