text=['# Full-text citation review — progress','', 'Pathologist review needed — LLM-generated summary/review.','', '**Status: in progress. The remaining full-text reviews are not complete.**','',f'- {summary["candidate_papers"]:,} candidate papers in the remaining queue.',f'- {summary["papers_with_claim_review"]} papers have at least one full-text claim decision; this is not a count of papers completely cleared.',f'- {summary["manual_claim_decisions"]} explicit claim decisions: '+', '.join(f'{v} {k.replace("_"," ")}' for k,v in summary['decision_counts'].items())+'.',f'- {summary["restored_report_placements"]} report citation placements now have confirmed full-text support, involving {summary["verified_primary_fulltext_pmids"]} distinct PMIDs.','', '## Access inventory','', '| Access result | Papers |','| --- | ---: |']
