text += [f'| {k.replace("_"," ")} | {v} |' for k,v in counts.items()]
text += ['','## Findings applied','', '- Restored primary observations for somatic AML, prostate, melanoma, myeloma, bladder, salivary and lung cancer findings where a specific Results section documented the gene/alteration.', '- Restored germline references for PALB2 cancer predisposition, BAP1 tumor predisposition, RB1 retinoblastoma, SDHB disorders, RAD51D ovarian predisposition, POLE/POLD1 polyposis, BRCA1 Fanconi anemia, NRAS Noonan syndrome, AKT3/PIK3R2 overgrowth, STAT3 hyper-IgE syndrome, FANCL Fanconi anemia, DOCK8 immunodeficiency, SPRED1 Legius syndrome and RBBP8 Jawad syndrome.', '- Routed the PIK3CA megalencephaly paper to its demonstrated mosaic-disease claim, without treating all cases as inherited disease.', '- Routed the SPOP structural paper to the normal-function statement, retaining its rejection for neurodevelopmental syndrome causality.', '- Kept the ICGC portal and TCGA project-overview papers out as primary evidence for gene-specific tumor claims.', '- Kept mouse-only, expression-only, and merely candidate-gene findings out of incompatible human disease statements.', '- Left ambiguous breast BRCA1/BRCA2 somatic counts and several syndrome-specific phenotypes pending supplementary-data review.','', '## Decisions','', '| PMID | Gene | Part | Decision | Evidence location / scope |','| --- | --- | --- | --- | --- |']
for r in d['decisions']:
 if r['pmid'] in ['21930502','24071849']:continue
 text.append(f'| [{r["pmid"]}](https://pubmed.ncbi.nlm.nih.gov/{r["pmid"]}/) | {r["symbol"]} | {r["part"]} | {r["decision"].replace("_"," ")} | {r["location"]} {r["support_scope"]} |')
text += ['', 'The two resource-paper rejections cover many gene-specific placements; every affected claim remains recorded in `curation/fulltext-review-decisions.json`. Full-text documents are cached outside the repository; source locations and content hashes are preserved.','', '## Reproduction','', '```sh','python3 "Knowledge Base/scripts/fetch-fulltext-reviews.py" PUBMED_CACHE FULLTEXT_CACHE','python3 "Knowledge Base/scripts/fetch-fulltext-jats.py" FULLTEXT_CACHE','# Record statement-specific decisions after reading the relevant primary results.','python3 "Knowledge Base/scripts/audit-report-citations.py"','python3 "Knowledge Base/scripts/build-hotspot-browser.py"','python3 "Knowledge Base/scripts/write-hotspot-review.py"','python3 "Knowledge Base/scripts/write-fulltext-review.py"','python3 "Knowledge Base/scripts/validate-citation-audit.py"','```']
